BEGIN;

-- Drop tables in reverse order if they exist for clean migrations
DROP TABLE IF EXISTS gemini_token_usage CASCADE;
DROP TABLE IF EXISTS gemini_rate_limits CASCADE;
DROP TABLE IF EXISTS gemini_cache CASCADE;
DROP TABLE IF EXISTS routine_recommendation_cache CASCADE;
DROP TABLE IF EXISTS alternative_finder_cache CASCADE;
DROP TABLE IF EXISTS ingredient_analysis_cache CASCADE;
DROP TABLE IF EXISTS price_check_logs CASCADE;
DROP TABLE IF EXISTS price_correction_submissions CASCADE;
DROP TABLE IF EXISTS manual_verification_requests CASCADE;
DROP TABLE IF EXISTS evidence_references CASCADE;
DROP TABLE IF EXISTS product_platform_ratings CASCADE;
DROP TABLE IF EXISTS product_reviews CASCADE;
DROP TABLE IF EXISTS user_routine_items CASCADE;
DROP TABLE IF EXISTS user_routines CASCADE;
DROP TABLE IF EXISTS user_preferences CASCADE;
DROP TABLE IF EXISTS user_profiles CASCADE;
DROP TABLE IF EXISTS wishlist CASCADE;
DROP TABLE IF EXISTS price_alerts CASCADE;
DROP TABLE IF EXISTS price_tracking CASCADE;
DROP TABLE IF EXISTS price_history CASCADE;
DROP TABLE IF EXISTS offers CASCADE;
DROP TABLE IF EXISTS products CASCADE;
DROP TABLE IF EXISTS stores CASCADE;
DROP TABLE IF EXISTS users CASCADE;

-- Table: users
CREATE TABLE users (
    id SERIAL PRIMARY KEY,
    display_name TEXT NOT NULL,
    email TEXT NOT NULL,
    password_hash TEXT NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    status TEXT DEFAULT 'active'
);

CREATE INDEX IF NOT EXISTS idx_users_email ON users(email);

-- Table: stores
CREATE TABLE stores (
    id SERIAL PRIMARY KEY,
    name TEXT NOT NULL,
    domain TEXT NOT NULL,
    rating DOUBLE PRECISION DEFAULT 4.5,
    shipping_policy TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);


-- Table: products
CREATE TABLE products (
    id SERIAL PRIMARY KEY,
    sku TEXT NOT NULL,
    title TEXT NOT NULL,
    brand TEXT NOT NULL,
    category TEXT NOT NULL,
    description TEXT,
    specs_json TEXT,
    image_url TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_products_brand ON products(brand);
CREATE INDEX IF NOT EXISTS idx_products_category ON products(category);

-- Table: offers
CREATE TABLE offers (
    id SERIAL PRIMARY KEY,
    product_id INTEGER NOT NULL,
    store_id INTEGER NOT NULL,
    current_price DOUBLE PRECISION NOT NULL,
    original_price DOUBLE PRECISION,
    shipping_cost DOUBLE PRECISION DEFAULT 0.0,
    currency TEXT DEFAULT 'USD',
    availability TEXT DEFAULT 'In Stock',
    variant_name TEXT DEFAULT 'Standard',
    condition TEXT DEFAULT 'Brand New',
    offer_url TEXT,
    last_checked TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
    FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_offers_store ON offers(store_id);
CREATE INDEX IF NOT EXISTS idx_offers_product ON offers(product_id);

-- Table: price_history
CREATE TABLE price_history (
    id SERIAL PRIMARY KEY,
    offer_id INTEGER NOT NULL,
    price DOUBLE PRECISION NOT NULL,
    currency TEXT DEFAULT 'USD',
    data_source TEXT DEFAULT 'demo_seed',
    data_status TEXT DEFAULT 'demo',
    recorded_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (offer_id) REFERENCES offers(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_price_history_offer_date ON price_history(offer_id, recorded_at);

-- Table: price_tracking
CREATE TABLE price_tracking (
    id SERIAL PRIMARY KEY,
    user_id INTEGER,
    product_id INTEGER NOT NULL,
    target_price DOUBLE PRECISION NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    status TEXT DEFAULT 'active',
    last_observed_price DOUBLE PRECISION,
    last_checked_at TIMESTAMP WITH TIME ZONE,
    last_alert_at TIMESTAMP WITH TIME ZONE,
    last_alert_price DOUBLE PRECISION,
    last_alert_type TEXT,
    alert_trigger_type TEXT DEFAULT 'target_or_drop',
    note TEXT,
    FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_tracking_status ON price_tracking(status);
CREATE INDEX IF NOT EXISTS idx_tracking_product ON price_tracking(product_id);
CREATE INDEX IF NOT EXISTS idx_tracking_user ON price_tracking(user_id);

-- Table: price_alerts
CREATE TABLE price_alerts (
    id SERIAL PRIMARY KEY,
    user_id INTEGER,
    tracking_id INTEGER NOT NULL,
    product_id INTEGER NOT NULL,
    alert_type TEXT NOT NULL,
    observed_price DOUBLE PRECISION NOT NULL,
    previous_price DOUBLE PRECISION,
    target_price DOUBLE PRECISION,
    message TEXT NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    is_read INTEGER DEFAULT 0,
    trigger_key TEXT,
    delivery_status TEXT DEFAULT 'in_app_delivered',
    channel TEXT DEFAULT 'in_app',
    FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE,
    FOREIGN KEY (tracking_id) REFERENCES price_tracking(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_alerts_is_read ON price_alerts(is_read);
CREATE INDEX IF NOT EXISTS idx_alerts_product ON price_alerts(product_id);
CREATE INDEX IF NOT EXISTS idx_alerts_tracking ON price_alerts(tracking_id);
CREATE INDEX IF NOT EXISTS idx_alerts_user ON price_alerts(user_id);

-- Table: wishlist
CREATE TABLE wishlist (
    id SERIAL PRIMARY KEY,
    user_id INTEGER NOT NULL,
    product_id INTEGER NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    note TEXT,
    FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_wishlist_product ON wishlist(product_id);
CREATE INDEX IF NOT EXISTS idx_wishlist_user ON wishlist(user_id);

-- Table: user_profiles
CREATE TABLE user_profiles (
    user_id INTEGER PRIMARY KEY,
    display_name TEXT,
    preferred_name TEXT,
    skin_type TEXT DEFAULT 'unsure',
    skin_concerns TEXT DEFAULT '[]',
    preferred_categories TEXT DEFAULT '[]',
    preferred_brands TEXT DEFAULT '[]',
    min_budget DOUBLE PRECISION,
    max_budget DOUBLE PRECISION,
    makeup_preferences TEXT DEFAULT '[]',
    ingredient_preferences TEXT DEFAULT '[]',
    ingredient_avoidance TEXT DEFAULT '[]',
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);


-- Table: user_preferences
CREATE TABLE user_preferences (
    user_id INTEGER PRIMARY KEY,
    preferred_categories TEXT DEFAULT '[]',
    preferred_brands TEXT DEFAULT '[]',
    min_budget DOUBLE PRECISION,
    max_budget DOUBLE PRECISION,
    preferred_store_id INTEGER,
    sort_preference TEXT DEFAULT 'best_deal',
    priority TEXT DEFAULT 'balanced',
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (preferred_store_id) REFERENCES stores(id) ON DELETE SET NULL,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);


-- Table: user_routines
CREATE TABLE user_routines (
    id SERIAL PRIMARY KEY,
    user_id INTEGER NOT NULL,
    routine_type TEXT NOT NULL,
    title TEXT NOT NULL,
    description TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_user_routines_type ON user_routines(user_id, routine_type);
CREATE INDEX IF NOT EXISTS idx_user_routines_user ON user_routines(user_id);

-- Table: user_routine_items
CREATE TABLE user_routine_items (
    id SERIAL PRIMARY KEY,
    routine_id INTEGER NOT NULL,
    product_id INTEGER,
    step_number INTEGER NOT NULL,
    step_name TEXT NOT NULL,
    custom_product_name TEXT,
    usage_instructions TEXT,
    precautions TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE SET NULL,
    FOREIGN KEY (routine_id) REFERENCES user_routines(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_routine_items_step ON user_routine_items(routine_id, step_number);
CREATE INDEX IF NOT EXISTS idx_routine_items_routine ON user_routine_items(routine_id);

-- Table: product_reviews
CREATE TABLE product_reviews (
    id SERIAL PRIMARY KEY,
    product_id INTEGER NOT NULL,
    platform TEXT NOT NULL,
    reviewer_name TEXT NOT NULL,
    rating DOUBLE PRECISION NOT NULL,
    rating_scale DOUBLE PRECISION DEFAULT 5.0,
    title TEXT,
    comment TEXT NOT NULL,
    review_date TEXT,
    verified_buyer INTEGER DEFAULT 0,
    skin_type TEXT,
    source_url TEXT,
    data_status TEXT DEFAULT 'demo',
    external_review_id TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_reviews_rating ON product_reviews(rating);
CREATE INDEX IF NOT EXISTS idx_reviews_platform ON product_reviews(platform);
CREATE INDEX IF NOT EXISTS idx_reviews_product ON product_reviews(product_id);

-- Table: product_platform_ratings
CREATE TABLE product_platform_ratings (
    id SERIAL PRIMARY KEY,
    product_id INTEGER NOT NULL,
    platform TEXT NOT NULL,
    average_rating DOUBLE PRECISION,
    review_count INTEGER,
    rating_scale DOUBLE PRECISION DEFAULT 5.0,
    data_source TEXT DEFAULT 'Retailer Feed (Demo)',
    product_url TEXT,
    last_verified TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_plat_ratings_product ON product_platform_ratings(product_id);

-- Table: evidence_references
CREATE TABLE evidence_references (
    id SERIAL PRIMARY KEY,
    reference_type TEXT NOT NULL,
    reference_id INTEGER NOT NULL,
    evidence_url TEXT NOT NULL,
    evidence_type TEXT,
    description TEXT,
    uploaded_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    uploaded_by INTEGER NOT NULL,
    FOREIGN KEY (uploaded_by) REFERENCES users(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_evidence_uploaded_by ON evidence_references(uploaded_by);
CREATE INDEX IF NOT EXISTS idx_evidence_reference ON evidence_references(reference_type, reference_id);

-- Table: manual_verification_requests
CREATE TABLE manual_verification_requests (
    id SERIAL PRIMARY KEY,
    user_id INTEGER NOT NULL,
    product_id INTEGER NOT NULL,
    retailer TEXT NOT NULL,
    product_url TEXT NOT NULL,
    user_submitted_price DOUBLE PRECISION,
    size_volume TEXT,
    shade TEXT,
    formulation TEXT,
    notes TEXT,
    status TEXT DEFAULT 'pending',
    verification_status TEXT,
    verified_price DOUBLE PRECISION,
    verified_mrp DOUBLE PRECISION,
    verified_discount_pct DOUBLE PRECISION,
    verified_shipping_fee DOUBLE PRECISION,
    verified_size_volume TEXT,
    verified_shade TEXT,
    verified_formulation TEXT,
    verified_product_name TEXT,
    verified_brand TEXT,
    verification_notes TEXT,
    source_url TEXT,
    submitted_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    verified_at TIMESTAMP WITH TIME ZONE,
    reviewed_at TIMESTAMP WITH TIME ZONE,
    reviewed_by INTEGER,
    rejection_reason TEXT,
    FOREIGN KEY (reviewed_by) REFERENCES users(id) ON DELETE SET NULL,
    FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_manual_verification_status ON manual_verification_requests(status);
CREATE INDEX IF NOT EXISTS idx_manual_verification_product ON manual_verification_requests(product_id);
CREATE INDEX IF NOT EXISTS idx_manual_verification_user ON manual_verification_requests(user_id);

-- Table: price_correction_submissions
CREATE TABLE price_correction_submissions (
    id SERIAL PRIMARY KEY,
    user_id INTEGER NOT NULL,
    product_id INTEGER NOT NULL,
    retailer TEXT NOT NULL,
    product_url TEXT NOT NULL,
    submitted_price DOUBLE PRECISION NOT NULL,
    submitted_mrp DOUBLE PRECISION,
    size_volume TEXT,
    shade TEXT,
    formulation TEXT,
    notes TEXT,
    evidence_url TEXT,
    status TEXT DEFAULT 'pending',
    reviewed_at TIMESTAMP WITH TIME ZONE,
    reviewed_by INTEGER,
    rejection_reason TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (reviewed_by) REFERENCES users(id) ON DELETE SET NULL,
    FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_price_correction_status ON price_correction_submissions(status);
CREATE INDEX IF NOT EXISTS idx_price_correction_product ON price_correction_submissions(product_id);
CREATE INDEX IF NOT EXISTS idx_price_correction_user ON price_correction_submissions(user_id);

-- Table: price_check_logs
CREATE TABLE price_check_logs (
    id SERIAL PRIMARY KEY,
    product_id INTEGER,
    retailer_id TEXT NOT NULL,
    retailer_name TEXT NOT NULL,
    product_url TEXT,
    canonical_url TEXT,
    status TEXT NOT NULL,
    listed_price DOUBLE PRECISION,
    mrp DOUBLE PRECISION,
    shipping_fee DOUBLE PRECISION,
    coupon_code TEXT,
    coupon_discount DOUBLE PRECISION,
    total_cost DOUBLE PRECISION,
    variant_detected TEXT,
    match_classification TEXT,
    checked_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    notes TEXT,
    FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE SET NULL
);

CREATE INDEX IF NOT EXISTS idx_price_check_logs_checked ON price_check_logs(checked_at);
CREATE INDEX IF NOT EXISTS idx_price_check_logs_retailer ON price_check_logs(retailer_id);
CREATE INDEX IF NOT EXISTS idx_price_check_logs_product ON price_check_logs(product_id);

-- Table: ingredient_analysis_cache
CREATE TABLE ingredient_analysis_cache (
    product_id INTEGER PRIMARY KEY,
    product_name TEXT NOT NULL,
    analysis_json TEXT NOT NULL,
    source TEXT NOT NULL,
    confidence_score DOUBLE PRECISION,
    created_at TEXT NOT NULL,
    FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE
);


-- Table: alternative_finder_cache
CREATE TABLE alternative_finder_cache (
    original_product_id INTEGER NOT NULL,
    criteria_hash TEXT NOT NULL,
    result_json TEXT NOT NULL,
    source TEXT NOT NULL,
    created_at TEXT NOT NULL,
    PRIMARY KEY (original_product_id, criteria_hash),
    FOREIGN KEY (original_product_id) REFERENCES products(id) ON DELETE CASCADE
);


-- Table: routine_recommendation_cache
CREATE TABLE routine_recommendation_cache (
    user_id INTEGER NOT NULL,
    routine_type TEXT NOT NULL,
    criteria_hash TEXT NOT NULL,
    result_json TEXT NOT NULL,
    source TEXT NOT NULL,
    created_at TEXT NOT NULL,
    PRIMARY KEY (user_id, routine_type, criteria_hash),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);


-- Table: gemini_cache
CREATE TABLE gemini_cache (
    cache_key TEXT,
    prompt TEXT NOT NULL,
    model TEXT NOT NULL,
    response TEXT NOT NULL,
    expires_at TEXT NOT NULL,
    created_at TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_gemini_cache_expires ON gemini_cache(expires_at);

-- Table: gemini_rate_limits
CREATE TABLE gemini_rate_limits (
    user_id INTEGER NOT NULL,
    date TEXT NOT NULL,
    count INTEGER DEFAULT 0,
    PRIMARY KEY (user_id, date)
);


-- Table: gemini_token_usage
CREATE TABLE gemini_token_usage (
    id SERIAL PRIMARY KEY,
    user_id INTEGER NOT NULL,
    model TEXT NOT NULL,
    prompt_tokens INTEGER NOT NULL,
    completion_tokens INTEGER NOT NULL,
    total_tokens INTEGER NOT NULL,
    success INTEGER NOT NULL,
    error_code TEXT,
    requested_at TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_token_usage_date ON gemini_token_usage(requested_at);
CREATE INDEX IF NOT EXISTS idx_token_usage_user ON gemini_token_usage(user_id);

