INSERT INTO products (id, sku, title, brand, category, description, specs_json, image_url, created_at) VALUES
    (1, 'LAP-MAC-M3-14', 'Apple MacBook Pro 14" (M3 Pro, 18GB RAM, 512GB SSD)', 'Apple', 'Laptops', 'Supercharged by M3 Pro chip featuring 11-core CPU and 14-core GPU, Liquid Retina XDR display, up to 18 hours battery life.', '{"Screen": "14.2-inch XDR", "Processor": "M3 Pro", "RAM": "18GB", "Storage": "512GB SSD", "Weight": "1.61 kg"}', 'https://images.unsplash.com/photo-1517336714731-489689fd1ca8?auto=format&fit=crop&w=600&q=80', '2026-11-09 07:09:25'),
    (2, 'LAP-DELL-XPS15', 'Dell XPS 15 OLED (Intel Core i7-13700H, 32GB RAM, 1TB SSD, RTX 4060)', 'Dell', 'Laptops', 'High-performance creator laptop with 3.5K OLED touchscreen, 13th Gen Intel Core processor, and NVIDIA GeForce RTX 4060 graphics.', '{"Screen": "15.6-inch 3.5K OLED", "Processor": "i7-13700H", "RAM": "32GB", "Storage": "1TB SSD", "GPU": "RTX 4060"}', 'https://images.unsplash.com/photo-1593642632823-8f785ba67e45?auto=format&fit=crop&w=600&q=80', '2026-11-09 07:09:25'),
