    (31, 'BEAUTY-MIN-MALEIC-50', 'Minimalist Maleic Bond Repair Complex 5% Hair Serum', 'Minimalist', 'Haircare', 'Patent-pending pre-shampoo bond repair treatment with Maleic Acid, Transglutaminase, and Amino Acids that repairs disulfide bonds broken by heat and coloring.', '{"Product Type": "Bond Repair Hair Treatment", "Net Quantity": "50 ml", "Key Ingredients": "Maleic Acid 5%, Transglutaminase, Amino Acids, Argan Oil", "Hair Type": "Damaged, Color-Treated, Frizzy, Heat-Styled", "Routine": "Weekly Pre-Shampoo", "Intended Use": "Hair bond repair, breakage reduction, frizz control", "Brand Tier": "Affordable", "Product URL": "https://beminimalist.co/products/maleic-bond-repair-complex-5-hair-serum", "Source": "Manufacturer Official D2C Portal & Label Declaration", "Evidence": "Public Cosmetics Packaging Declaration / INCI Filing", "Data Status": "catalog_verified"}', 'https://images.unsplash.com/photo-1522337360788-8b13dee7a37e?auto=format&fit=crop&w=600&q=80', '2026-11-09 07:09:25'),
    (32, 'BEAUTY-CAP-BODYWASH-250', 'Chemist at Play Exfoliating Lactic Acid Body Wash', 'Chemist at Play', 'Body care', 'Ceramide-infused daily exfoliating body wash with 2% Lactic Acid and Zemea to buff away strawberry skin, rough bumps, and back acne gently.', '{"Product Type": "Exfoliating Body Wash", "Net Quantity": "250 ml", "Key Ingredients": "Lactic Acid 2%, Essential Ceramides, Zemea, Vitamin E", "Skin Type": "Rough Bumpy Skin, Strawberry Legs, Normal", "Routine": "Daily Body Routine", "Intended Use": "Keratosis pilaris reduction, skin smoothing, barrier hydration", "Brand Tier": "Affordable", "Product URL": "https://innovist.com/products/chemist-at-play-exfoliating-body-wash-with-lactic-acid-and-zemia", "Source": "Manufacturer Official D2C Portal & Label Declaration", "Evidence": "Public Cosmetics Packaging Declaration / INCI Filing", "Data Status": "catalog_verified"}', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=600&q=80', '2026-11-09 07:09:25'),
    (998, 'TEST-VIT-C-002', 'Cheaper Vitamin C Serum', 'OtherBrand', 'Serum', NULL, '{"Key Ingredients": "Vitamin C, Hyaluronic Acid", "Product Type": "Serum", "Net Quantity": "30ml"}', NULL, '2026-11-09 18:49:33'),
    (999, 'TEST-VIT-C-001', 'Test Vitamin C Serum', 'TestBrand', 'Serum', 'A test serum', '{"Key Ingredients": "Vitamin C, Hyaluronic Acid, Ferulic Acid", "Product Type": "Serum", "Net Quantity": "30ml"}', NULL, '2026-11-09 18:49:33'),
    (1000, 'BEAUTY-MINIMALIST-SUN-40', 'Minimalist Invisible Sunscreen SPF 40 with Tomato Fruit Extract', 'Minimalist', 'Sunscreens', 'Transparent silicone gel sunscreen with SPF 40 and PA+++ rating, enriched with antioxidant Tomato Fruit extract that leaves zero white cast and no greasy residue.', '{"Product Type": "Gel Sunscreen", "Net Quantity": "50 g", "Key Ingredients": "Tomato Fruit Extract, Uvinul A Plus, Octisalate, Homosalate", "Skin Type": "Normal, Dry, Sensitive", "Skin Concerns": "Sun Protection, Dullness, Uneven Tone", "Routine": "AM", "Brand Tier": "Affordable", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://beminimalist.co/products/invisible-sunscreen-spf-40"}', 'https://images.unsplash.com/photo-1598440947619-2c35fc9aa908?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
    (1001, 'BEAUTY-AQUAL-GLOW-SUN-50', 'Aqualogica Glow+ Dewy Sunscreen SPF 50+ PA++++ with Papaya & Vitamin C', 'Aqualogica', 'Sunscreens', 'Ultra-lightweight hydrating sunscreen formulated with water-lock technology, Papaya extracts, and Vitamin C to deliver a radiant dewy finish without stickiness.', '{"Product Type": "Dewy Fluid Sunscreen", "Net Quantity": "50 g", "Key Ingredients": "Papaya Extract, Vitamin C, Hyaluronic Acid, Zinc Oxide, Titanium Dioxide", "Skin Type": "All Skin Types, Dull Skin", "Skin Concerns": "Sun Protection, Dullness, Tanning", "Routine": "AM", "Brand Tier": "Affordable", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://aqualogica.in/products/glow-dewy-sunscreen-spf-50"}', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
    (1002, 'BEAUTY-DRSHETHS-CERAMIDE-SUN-50', 'Dr. Sheth''s Ceramide & Vitamin C Sunscreen SPF 50+ PA++++', 'Dr. Sheth''s', 'Sunscreens', 'Formulated specifically for Indian skin, combining 1% Ceramide Complex to rebuild the skin barrier with 1% Vitamin C to protect against UV and blue light.', '{"Product Type": "Lotion Sunscreen", "Net Quantity": "50 g", "Key Ingredients": "Ceramide Complex 1%, Vitamin C 1%, Hyaluronic Acid, Micro-encapsulated Filters", "Skin Type": "Sensitive, Normal, Dry", "Skin Concerns": "Sun Protection, Barrier Repair, Pigmentation", "Routine": "AM", "Brand Tier": "Affordable", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://drsheths.com/products/ceramide-vitamin-c-sunscreen"}', 'https://images.unsplash.com/photo-1598440947619-2c35fc9aa908?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
    (1003, 'BEAUTY-NEUTROGENA-SHEER-SUN-88', 'Neutrogena Ultra Sheer Dry-Touch Sunscreen SPF 50+ PA++++', 'Neutrogena', 'Sunscreens', 'Iconic matte-finish sunscreen featuring Helioplex broad spectrum UVA/UVB technology with Dry-Touch silica microspheres for clean, non-greasy all-day wear.', '{"Product Type": "Dry-Touch Sunscreen", "Net Quantity": "88 ml", "Key Ingredients": "Helioplex Technology, Avobenzone, Oxybenzone, Silica", "Skin Type": "Oily, Normal, Combination", "Skin Concerns": "Sun Protection, Oil Control, Shine", "Routine": "AM", "Brand Tier": "Drugstore", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://www.neutrogena.in/sun-care/ultra-sheer-dry-touch-sunscreen-spf-50-plus"}', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
    (1004, 'BEAUTY-FOXTALE-GLOW-SUN-50', 'Foxtale Daily Glow Sunscreen SPF 50 PA++++ with Vitamin C & Niacinamide', 'Foxtale', 'Sunscreens', 'Infused with photostable modern European filters, Vitamin C, and Niacinamide, this daily sunscreen brightens dull complexion while providing robust UV defense.', '{"Product Type": "Brightening Sunscreen", "Net Quantity": "50 ml", "Key Ingredients": "Niacinamide, Vitamin C, Tinosorb S, Uvinul T 150", "Skin Type": "All Skin Types, Dull Skin", "Skin Concerns": "Sun Protection, Dullness, Uneven Tone", "Routine": "AM", "Brand Tier": "Affordable", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://foxtale.in/products/daily-glow-sunscreen-spf-50"}', 'https://images.unsplash.com/photo-1598440947619-2c35fc9aa908?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
    (1005, 'BEAUTY-CONSCIOUS-SUNDRINK-50', 'Conscious Chemist Sundrink Hybrid Sunscreen SPF 50 PA++++', 'Conscious Chemist', 'Sunscreens', 'Ultra-lightweight milk sunscreen featuring a ceramide complex and modern photostable hybrid filters that absorb instantly without white cast or pore clogging.', '{"Product Type": "Fluid Milk Sunscreen", "Net Quantity": "50 g", "Key Ingredients": "Ceramide Complex, Niacinamide, Uvinul A Plus, Tinosorb M", "Skin Type": "Acne-Prone, Sensitive, Oily", "Skin Concerns": "Sun Protection, Redness, Barrier Repair", "Routine": "AM", "Brand Tier": "Affordable", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://consciouschemist.com/products/sundrink-hybrid-sunscreen-spf-50"}', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
    (1006, 'BEAUTY-DOTKEY-CICA-SUN-50', 'Dot & Key Cica Calming Sunscreen SPF 50+ PA++++ with Green Tea', 'Dot & Key', 'Sunscreens', 'Dermatologically tested mineral-infused calming sunscreen formulated with fermented Cica and Green Tea to soothe active breakouts while shielding from UV.', '{"Product Type": "Calming Sunscreen Gel", "Net Quantity": "50 g", "Key Ingredients": "Centella Asiatica (Cica), Niacinamide, Green Tea Extract, Zinc Oxide", "Skin Type": "Acne-Prone, Sensitive, Oily", "Skin Concerns": "Active Acne, Redness, Sun Protection", "Routine": "AM", "Brand Tier": "Affordable", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://dotandkey.com/products/cica-calming-sunscreen-spf-50"}', 'https://images.unsplash.com/photo-1598440947619-2c35fc9aa908?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
    (1007, 'BEAUTY-PLUM-RICE-SUN-50', 'Plum 2% Niacinamide & Rice Water Sunscreen SPF 50 PA+++', 'Plum', 'Sunscreens', 'Hybrid fluid sunscreen with 2% Niacinamide and Japanese fermented rice water that nourishes, prevents hyperpigmentation, and imparts a natural dewy glow.', '{"Product Type": "Fluid Sunscreen", "Net Quantity": "50 g", "Key Ingredients": "Niacinamide 2%, Fermented Rice Water, Hybrid UV Filters", "Skin Type": "Combination, Oily, Blemish-Prone", "Skin Concerns": "Sun Protection, Blemishes, Uneven Tone", "Routine": "AM", "Brand Tier": "Affordable", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://plumgoodness.com/products/2-niacinamide-rice-water-hybrid-sunscreen-spf-50-pa"}', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
    (1008, 'BEAUTY-DERMACO-ZINC-SUN-50', 'The Derma Co Pure Zinc Matte Sunscreen Gel SPF 30 PA+++', 'The Derma Co', 'Sunscreens', '100% mineral sunscreen formulated with 100% Zinc Oxide and Titanium Dioxide. Designed for post-procedure and highly sensitized skin with zero chemical irritants.', '{"Product Type": "Mineral Sunscreen Gel", "Net Quantity": "50 g", "Key Ingredients": "100% Mineral Zinc Oxide, Titanium Dioxide, Vitamin E", "Skin Type": "Highly Sensitive, Post-Procedure, Acne-Prone", "Skin Concerns": "Severe Sensitivity, Sun Allergy, Irritation", "Routine": "AM", "Brand Tier": "Affordable", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://thedermaco.com/products/pure-zinc-matte-sunscreen-gel-spf-30"}', 'https://images.unsplash.com/photo-1598440947619-2c35fc9aa908?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
    (1009, 'BEAUTY-MINIMALIST-MULTI-SUN-50', 'Minimalist SPF 50 Sunscreen with Multi-Vitamins & CICA', 'Minimalist', 'Sunscreens', 'Broad-spectrum SPF 50 PA++++ sunscreen powered by 4 modern UV filters, Vitamin B5 (Panthenol), Vitamin F, and Centella Asiatica to soothe and repair skin during UV exposure.', '{"Product Type": "Light Cream Sunscreen", "Net Quantity": "50 g", "Key Ingredients": "Vitamin B5, Vitamin F, Centella Asiatica, Tinosorb S, Uvinul A Plus", "Skin Type": "All Skin Types, Sensitive", "Skin Concerns": "Sun Protection, Dryness, Barrier Support", "Routine": "AM", "Brand Tier": "Affordable", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://beminimalist.co/products/multi-vitamin-spf-50-sunscreen"}', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
    (1010, 'BEAUTY-AQUAL-RAD-SUN-50', 'Aqualogica Radiance+ Dewy Sunscreen SPF 50+ PA++++ with Watermelon', 'Aqualogica', 'Sunscreens', 'Formulated with Watermelon and Niacinamide to protect against sun damage, prevent pigmentation, and impart an ultra-dewy glass-skin finish with zero white cast.', '{"Product Type": "Dewy Gel Sunscreen", "Net Quantity": "50 g", "Key Ingredients": "Watermelon Extract, Niacinamide, Hyaluronic Acid, Tinosorb M", "Skin Type": "Dehydrated, Combination, Normal", "Skin Concerns": "Sun Protection, Dullness, Glass Skin", "Routine": "AM", "Brand Tier": "Affordable", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://aqualogica.in/products/radiance-dewy-sunscreen-spf-50"}', 'https://images.unsplash.com/photo-1598440947619-2c35fc9aa908?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
    (1011, 'BEAUTY-REEQUIL-OMCFREE-SUN-50', 'Re''equil Oxybenzone and OMC Free Sunscreen SPF 50 PA+++', 'Re''equil', 'Sunscreens', 'Specially formulated for oily, acne-prone and sensitive skin without endocrine-disrupting chemicals. Non-comedogenic and certified coral-reef safe.', '{"Product Type": "Lotion Sunscreen", "Net Quantity": "50 g", "Key Ingredients": "Eurol BT, Zinc Oxide, Titanium Dioxide, Tocopherol", "Skin Type": "Acne-Prone, Sensitive, Oily", "Skin Concerns": "Sun Protection, Acne Breakouts, Reef Safety", "Routine": "AM", "Brand Tier": "Mid-Range", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://www.reequil.com/products/oxybenzone-omc-free-sunscreen"}', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
    (1012, 'BEAUTY-CETAPHIL-LIGHTGEL-SUN-50', 'Cetaphil Sun SPF 50+ Very High Protection Light Gel', 'Cetaphil', 'Sunscreens', 'Dermatologist-recommended hypoallergenic light gel sunscreen providing very high broad spectrum UV and IR radiation protection. Oil-free, fragrance-free, and water-resistant.', '{"Product Type": "Light Gel Sunscreen", "Net Quantity": "50 ml", "Key Ingredients": "Vitamin E, Aloe Vera, Broad Spectrum UVA/UVB Filters", "Skin Type": "Extreme Sensitive, Dermatitis-Prone, Normal", "Skin Concerns": "All-Day Wear", "Routine": "AM", "Brand Tier": "Mid-Range", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://www.cetaphil.in/sun-care/sun-spf-50-plus-light-gel"}', 'https://images.unsplash.com/photo-1598440947619-2c35fc9aa908?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
    (1013, 'BEAUTY-MINIMALIST-SALICYLIC-30', 'Minimalist 2% Salicylic Acid Face Serum with Oligopeptide', 'Minimalist', 'Serums', 'Daily gentle exfoliating serum with 2% Salicylic Acid (BHA) and anti-microbial Oligopeptide-10 that penetrates deep into pores to dissolve sebum, dirt, and blackheads.', '{"Product Type": "Active Face Serum", "Net Quantity": "30 ml", "Key Ingredients": "Salicylic Acid 2%, Oligopeptide-10, EGCG (Green Tea Extract), Aloe Juice", "Skin Type": "Acne-Prone, Oily, Blackhead-Prone", "Skin Concerns": "Acne, Blackheads, Enlarged Pores", "Routine": "PM", "Brand Tier": "Affordable", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://beminimalist.co/products/salicylic-acid-2"}', 'https://images.unsplash.com/photo-1620916566398-39f1143ab7be?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
    (1014, 'BEAUTY-MINIMALIST-VITC-16-30', 'Minimalist 16% Vitamin C Face Serum with Ferulic Acid', 'Minimalist', 'Serums', 'High-potency antioxidant serum formulated with 16% stabilized Ethyl Ascorbic Acid, 1% Ferulic Acid, and Fullerenes to target dark spots, collagen synthesis, and sun damage.', '{"Product Type": "Brightening Serum", "Net Quantity": "30 ml", "Key Ingredients": "Ethyl Ascorbic Acid 16%, Ferulic Acid 1%, Fullerenes, Hyaluronic Acid", "Skin Type": "Dull, Uneven Tone, Mature", "Skin Concerns": "Dark Spots, Dullness, Fine Lines", "Routine": "AM", "Brand Tier": "Affordable", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://beminimalist.co/products/vitamin-c-16"}', 'https://images.unsplash.com/photo-1620916566398-39f1143ab7be?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
    (1015, 'BEAUTY-DERMACO-KOJIC-30', 'The Derma Co 2% Kojic Acid Face Serum with 1% Alpha Arbutin', 'The Derma Co', 'Serums', 'Clinically proven dermatological solution designed to treat melasma, stubborn dark spots, and post-acne marks with 2% Kojic Acid and 1% Alpha Arbutin.', '{"Product Type": "Depigmentation Serum", "Net Quantity": "30 ml", "Key Ingredients": "Kojic Acid 2%, Alpha Arbutin 1%, Niacinamide 1%, Hyaluronic Acid", "Skin Type": "Pigmented, Uneven Tone, All Skin Types", "Skin Concerns": "Melasma, Dark Spots, Post-Acne Scars", "Routine": "AM & PM", "Brand Tier": "Affordable", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://thedermaco.com/products/2-percent-kojic-acid-face-serum"}', 'https://images.unsplash.com/photo-1608248597359-25f0376ef79d?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12');
