    (1016, 'BEAUTY-DERMACO-VITC-10-30', 'The Derma Co 10% Vitamin C Face Serum with 5% Niacinamide', 'The Derma Co', 'Serums', 'Dual-action glow serum combining 10% 3-O-Ethyl Ascorbic Acid with 5% Niacinamide and Ferulic Acid to visibly fade pigmentation and protect from free radical damage.', '{"Product Type": "Glow Serum", "Net Quantity": "30 ml", "Key Ingredients": "3-O-Ethyl Ascorbic Acid 10%, Niacinamide 5%, Ferulic Acid 0.5%", "Skin Type": "All Skin Types, Dull Skin", "Skin Concerns": "Dullness, Dark Spots, Sun Damage", "Routine": "AM", "Brand Tier": "Affordable", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://thedermaco.com/products/10-percent-vitamin-c-face-serum"}', 'https://images.unsplash.com/photo-1620916566398-39f1143ab7be?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
