    (1043, 'BEAUTY-DERMACO-SALICYLIC-WASH-100', 'The Derma Co 1% Salicylic Acid Gel Face Wash', 'The Derma Co', 'Face cleansers', 'Targeted anti-acne gel face wash with 1% Salicylic Acid and Witch Hazel that deeply purifies oily skin and clears active pustules without disrupting moisture balance.', '{"Product Type": "Anti-Acne Gel Wash", "Net Quantity": "100 ml", "Key Ingredients": "Salicylic Acid 1%, Witch Hazel Extract, Willow Bark, Vitamin E", "Skin Type": "Oily, Acne-Prone, Large Pores", "Skin Concerns": "Active Acne, Clogged Pores, Excess Sebum", "Routine": "AM & PM", "Brand Tier": "Affordable", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://thedermaco.com/products/1-percent-salicylic-acid-gel-face-wash"}', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
    (1044, 'BEAUTY-DOTKEY-BARRIER-CLEANSER-100', 'Dot & Key Barrier Repair Gentle Hydrating Cleanser', 'Dot & Key', 'Face cleansers', 'Cream-to-lather barrier strengthening cleanser infused with 5 Essential Ceramides and Japanese Rice Water to dissolve makeup and impurities without tight skin feeling.', '{"Product Type": "Hydrating Cream Cleanser", "Net Quantity": "100 ml", "Key Ingredients": "5 Essential Ceramides, Hyaluronic Acid, Japanese Rice Water", "Skin Type": "Sensitive, Dry, All Skin Types", "Skin Concerns": "Skin Tightness, Barrier Repair, Daily Dirt", "Routine": "AM & PM", "Brand Tier": "Affordable", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://dotandkey.com/products/barrier-repair-gentle-hydrating-face-wash"}', 'https://images.unsplash.com/photo-1598440947619-2c35fc9aa908?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
    (1045, 'BEAUTY-PLUM-GREENTEA-WASH-100', 'Plum Green Tea Pore Cleansing Face Wash', 'Plum', 'Face cleansers', 'Soap-free foaming wash packed with Green Tea antioxidants and gentle cellulose scrub beads that thoroughly unclogs pores and washes away acne-causing bacteria.', '{"Product Type": "Clarifying Foam Wash", "Net Quantity": "100 ml", "Key Ingredients": "Green Tea Extract, Glycolic Acid, Soft Cellulose Beads", "Skin Type": "Oily, Combination, Acne-Prone", "Skin Concerns": "Dead Skin Buildup, Congestion, Acne", "Routine": "AM & PM", "Brand Tier": "Affordable", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://plumgoodness.com/products/green-tea-pore-cleansing-face-wash"}', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
    (1046, 'BEAUTY-SIMPLE-REFRESH-WASH-150', 'Simple Kind to Skin Refreshing Facial Wash', 'Simple', 'Face cleansers', '100% soap-free clean gel cleanser enriched with Pro-Vitamin B5 and Vitamin E that purifies sensitive skin without artificial perfumes, colorants, or harsh chemicals.', '{"Product Type": "Soap-Free Gel Wash", "Net Quantity": "150 ml", "Key Ingredients": "Pro-Vitamin B5, Vitamin E, Triple Purified Water", "Skin Type": "100% Sensitive Skin, All Skin Types", "Skin Concerns": "Sensitivity, Chemical Irritation, Daily Cleansing", "Routine": "AM & PM", "Brand Tier": "Drugstore", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://www.simpleskincare.in/products/kind-to-skin-refreshing-facial-wash"}', 'https://images.unsplash.com/photo-1598440947619-2c35fc9aa908?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
    (1047, 'BEAUTY-BIODERMA-SENSIBIO-H2O-100', 'Bioderma Sensibio H2O Micellar Water Make-up Removing Biphasic', 'Bioderma', 'Face cleansers', 'Dermatological cult-favorite micellar water that captures impurities and waterproof makeup while respecting skin''s natural hydrolipidic film and physiological pH 5.5.', '{"Product Type": "Micellar Solution", "Net Quantity": "100 ml", "Key Ingredients": "Micellar Technology, Cucumber Extract, Fructooligosaccharides", "Skin Type": "Sensitive, Intolerant, All Skin Types", "Skin Concerns": "Makeup Removal, Environmental Pollution, Irritation", "Routine": "PM", "Brand Tier": "Prestige", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://www.bioderma.co.in/our-products/sensibio/h2o"}', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
    (1048, 'BEAUTY-CETAPHIL-DAILY-CLEANSER-125', 'Cetaphil Daily Facial Cleanser for Combination Skin', 'Cetaphil', 'Face cleansers', 'Clinically proven low-lather foaming cleanser with Niacinamide and Glycerin that removes up to 99% of excess surface oils, dirt, and light makeup without over-drying.', '{"Product Type": "Low-Lather Cleanser", "Net Quantity": "125 ml", "Key Ingredients": "Glycerin, Niacinamide (Vitamin B3), Panthenol (Vitamin B5)", "Skin Type": "Combination, Oily, Sensitive", "Skin Concerns": "T-Zone Oiliness, Enlarged Pores, Daily Dust", "Routine": "AM & PM", "Brand Tier": "Mid-Range", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://www.cetaphil.in/cleansers/daily-facial-cleanser"}', 'https://images.unsplash.com/photo-1598440947619-2c35fc9aa908?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
    (1049, 'BEAUTY-CERAVE-HYDRATING-CLEANSER-236', 'CeraVe Hydrating Facial Cleanser for Normal to Dry Skin', 'CeraVe', 'Face cleansers', 'Developed with dermatologists, this non-foaming lotion cleanser features 3 Essential Ceramides and Hyaluronic Acid with MVE delivery technology for 24-hr moisture.', '{"Product Type": "Lotion Cleanser", "Net Quantity": "236 ml", "Key Ingredients": "Ceramides 1, 3, 6-II, Hyaluronic Acid, Glycerin, Cholesterol", "Skin Type": "Normal, Dry, Sensitive", "Skin Concerns": "Dryness, Barrier Maintenance, Eczema", "Routine": "AM & PM", "Brand Tier": "Drugstore", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://www.cerave.in/our-products/cleansers/hydrating-facial-cleanser"}', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
    (1050, 'BEAUTY-DRSHETHS-OIL-CLEANSER-100', 'Dr. Sheth''s Ceramide & Vitamin C Oil Cleanser', 'Dr. Sheth''s', 'Face cleansers', 'First-cleanse emulsifying oil cleanser formulated with Ceramide complex and lipid-soluble Vitamin C that effortlessly melts stubborn waterproof mascara and SPF.', '{"Product Type": "Emulsifying Cleansing Oil", "Net Quantity": "100 ml", "Key Ingredients": "Ceramide Complex, Ascorbyl Tetraisopalmitate, Olive Oil, Vitamin E", "Skin Type": "All Skin Types, Waterproof Makeup Wearers", "Skin Concerns": "Waterproof Makeup Removal, Stubborn Sunscreen Removal", "Routine": "PM", "Brand Tier": "Affordable", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://drsheths.com/products/ceramide-vitamin-c-oil-cleanser"}', 'https://images.unsplash.com/photo-1598440947619-2c35fc9aa908?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
    (1051, 'BEAUTY-FOXTALE-DUET-CLEANSER-100', 'Foxtale The Daily Duet Gentle Hydrating Cleanser', 'Foxtale', 'Face cleansers', 'Two-in-one gentle makeup remover and hydrating cleanser infused with Sodium Hyaluronate and Red Algae extract that leaves skin clean, soft, and refreshed.', '{"Product Type": "2-in-1 Hydrating Cleanser", "Net Quantity": "100 ml", "Key Ingredients": "Sodium Hyaluronate, Red Algae Extract, Vitamin B5", "Skin Type": "All Skin Types, Dry, Normal", "Skin Concerns": "Double Cleansing Substitute, Dryness, Makeup", "Routine": "AM & PM", "Brand Tier": "Affordable", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://foxtale.in/products/daily-duet-face-wash"}', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
