    (1056, 'BEAUTY-LAKME-9TO5-FOUNDATION-25', 'Lakme 9 to 5 Primer + Matte Perfect Cover Foundation - Warm Natural', 'Lakme', 'Foundations', 'Convenient built-in primer foundation that evens out skin tone, covers fine lines, and delivers a comfortable work-day matte finish with SPF 20 sun protection.', '{"Product Type": "Primer + Foundation", "Net Quantity": "25 ml", "Key Ingredients": "Silicone Primer Complex, Vitamin E, SPF 20 Sun Filters", "Skin Type": "All Skin Types, Oily, Normal", "Skin Concerns": "Office Wear, Quick Routine, Pores", "Routine": "AM", "Brand Tier": "Affordable", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://www.lakmeindia.com/products/lakme-9to5-primer-matte-foundation"}', 'https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
    (1057, 'BEAUTY-SUGAR-ACEOFFACE-12', 'Sugar Cosmetics Ace of Face Foundation Stick - 15 Cappuccino', 'Sugar Cosmetics', 'Foundations', 'Multi-purpose portable stick foundation with a built-in brush applicator that glides effortlessly across skin to provide lightweight velvet matte full coverage.', '{"Product Type": "Foundation Stick", "Net Quantity": "12 g", "Key Ingredients": "Candelilla Wax, Vitamin E, Micronized Pigments, Silica", "Skin Type": "Combination, Oily, Normal", "Skin Concerns": "On-The-Go Touchups, Full Coverage, Contouring", "Routine": "AM", "Brand Tier": "Affordable", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://in.sugarcosmetics.com/products/ace-of-face-foundation-stick"}', 'https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
