    (1059, 'BEAUTY-NYKAA-ALLDAYMATTE-30', 'Nykaa All Day Matte Long Wear Liquid Foundation - Warm Sand', 'Nykaa', 'Foundations', 'Formulated specifically for Indian tropical climates, this oil-controlling liquid foundation stays put through heat and humidity without settling into smile lines.', '{"Product Type": "Matte Liquid Foundation", "Net Quantity": "30 ml", "Key Ingredients": "Vitamin E, Oil-Absorbing Polymers, Dimethicone", "Skin Type": "Oily, Combination", "Skin Concerns": "Humidity Shine, Meltdown, Uneven Tone", "Routine": "AM", "Brand Tier": "Affordable", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://www.nykaa.com/nykaa-all-day-matte-foundation/p/945678"}', 'https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
    (1060, 'BEAUTY-SWISS-HIGHCOVER-50', 'Swiss Beauty High Coverage Waterproof Foundation - 02 Warm Nude', 'Swiss Beauty', 'Foundations', 'Ultra-affordable high-pigment bridal foundation that provides full porcelain coverage, conceals severe blemishes, and resists water and sweat for special events.', '{"Product Type": "Waterproof Full Foundation", "Net Quantity": "50 g", "Key Ingredients": "Jojoba Oil, Titanium Dioxide, Vitamin E, Mineral Wax", "Skin Type": "All Skin Types, Blemish-Prone", "Skin Concerns": "Blemish Camouflage, Event Longwear", "Routine": "AM", "Brand Tier": "Affordable", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://swissbeauty.in/products/high-coverage-waterproof-foundation"}', 'https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
    (1061, 'BEAUTY-PLUM-SOFTBLEND-30', 'Plum Soft Blend Liquid Foundation - 120 Warm Sand', 'Plum', 'Foundations', '100% vegan clean beauty foundation infused with Centella Asiatica and Hyaluronic Acid that hydrates like skincare while imparting seamless medium skin-like finish.', '{"Product Type": "Clean Liquid Foundation", "Net Quantity": "30 ml", "Key Ingredients": "Centella Asiatica, Hyaluronic Acid, Vitamin E", "Skin Type": "Sensitive, Normal, Dry", "Skin Concerns": "Chemical Irritation, Clean Makeup, Hydration", "Routine": "AM", "Brand Tier": "Affordable", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://plumgoodness.com/products/soft-blend-liquid-foundation"}', 'https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
    (1062, 'BEAUTY-CLINIQUE-EVENBETTER-30', 'Clinique Even Better Makeup Broad Spectrum SPF 15 Foundation - CN 52', 'Clinique', 'Foundations', 'Dermatologist-developed treatment foundation with Vitamin C and Salicylic Acid that actively reduces dark spots and improves skin clarity with every application.', '{"Product Type": "Skincare-Infused Foundation", "Net Quantity": "30 ml", "Key Ingredients": "Vitamin C, Salicylic Acid, SPF 15 Sun Filters, Grapefruit Peel Extract", "Skin Type": "Hyperpigmented, Sensitive, Dry to Combination", "Skin Concerns": "Age Spots, Discoloration, Sensitive Skin Base", "Routine": "AM", "Brand Tier": "Luxury", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://www.clinique.in/product/1599/5276/makeup/foundations/even-better-makeup-broad-spectrum-spf-15"}', 'https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
    (1063, 'BEAUTY-MAYBELLINE-MATTEINK-PIONEER-5', 'Maybelline Super Stay Matte Ink Liquid Lipstick - 20 Pioneer', 'Maybelline', 'Lipsticks', 'The global benchmark in liquid lipsticks: up to 16-hour saturated transfer-proof pigment with a unique arrow applicator for precise flawless coverage.', '{"Product Type": "Liquid Matte Lipstick", "Net Quantity": "5 ml", "Key Ingredients": "High-Intensity Colorants, Dimethicone, Silica", "Skin Type": "All Skin Tones", "Skin Concerns": "Lip Color Bleeding, Non-Transfer, Food-Proof", "Routine": "AM & PM", "Brand Tier": "Drugstore", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://www.maybelline.co.in/lip-makeup/lipstick/superstay-matte-ink-liquid-lipstick"}', 'https://images.unsplash.com/photo-1586495777744-4413f21062fa?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
    (1064, 'BEAUTY-MAC-POWDERKISS-CHILI-3', 'M.A.C Powder Kiss Lipstick - Devoted To Chili', 'M.A.C', 'Lipsticks', 'Zero-shine weightless moisture-matte lipstick featuring moisture-coated powder pigments that condition and hydrate lips with a romantic soft-focus blur.', '{"Product Type": "Powder Matte Lipstick", "Net Quantity": "3 g", "Key Ingredients": "Moisture-Coated Powder Pigments, Vitamin E, Dimethicone", "Skin Type": "All Skin Tones", "Skin Concerns": "Dry Flaky Matte Lips, Blurred Lip Look", "Routine": "AM & PM", "Brand Tier": "Luxury", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://www.maccosmetics.in/product/13854/60284/products/makeup/lips/lipstick/powder-kiss-lipstick"}', 'https://images.unsplash.com/photo-1586495777744-4413f21062fa?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
    (1065, 'BEAUTY-KAYBEAUTY-DRAMA-ROLLON-38', 'Kay Beauty Matte Drama Matte Lipstick - Roll On', 'Kay Beauty', 'Lipsticks', 'Infused with Red Raspberry and Grape Seed Oil, this luxurious velvet bullet lipstick glides like silk and locks in rich pigment with a hydrating cushion matte finish.', '{"Product Type": "Velvet Bullet Lipstick", "Net Quantity": "3.8 g", "Key Ingredients": "Red Raspberry Extract, Grape Seed Oil, Vitamin E", "Skin Type": "All Skin Tones", "Skin Concerns": "Comfortable Longwear, Deep Berry Hue", "Routine": "AM & PM", "Brand Tier": "Mid-Range", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://www.nykaa.com/kay-beauty-matte-drama-matte-lipstick/p/623456"}', 'https://images.unsplash.com/photo-1586495777744-4413f21062fa?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12');
