    (1066, 'BEAUTY-NYKAA-ULTRAMATTE-DIANA-38', 'Nykaa Ultra Matte Lipstick - Diana', 'Nykaa', 'Lipsticks', 'Bestselling cult Indian nude brown bullet lipstick formulated with Jojoba and Olive oil that provides intense opaque matte pigment in a single effortless swipe.', '{"Product Type": "Matte Bullet Lipstick", "Net Quantity": "3.8 g", "Key Ingredients": "Olive Oil, Jojoba Oil, Vitamin E, Carnauba Wax", "Skin Type": "Warm & Dusky Indian Undertones", "Skin Concerns": "Perfect Everyday Nude, Pigmented Lips", "Routine": "AM & PM", "Brand Tier": "Affordable", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://www.nykaa.com/nykaa-ultra-matte-lipstick-diana/p/456789"}', 'https://images.unsplash.com/photo-1586495777744-4413f21062fa?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
    (1067, 'BEAUTY-SUGAR-MATTEASHELL-SCARLETT-28', 'Sugar Matte As Hell Crayon Lipstick - 01 Scarlett O''Hara', 'Sugar Cosmetics', 'Lipsticks', 'High-definition lipstick crayon featuring bold velvet matte formula with extreme color payoff that defines, shapes, and fills lips with fiery red drama.', '{"Product Type": "Crayon Lipstick", "Net Quantity": "2.8 g", "Key Ingredients": "Candelilla Wax, Carnauba Wax, Vitamin E, Mineral Colorants", "Skin Type": "All Skin Tones", "Skin Concerns": "Precise Lip Lining, Bold Pigment", "Routine": "AM & PM", "Brand Tier": "Affordable", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://in.sugarcosmetics.com/products/matte-as-hell-crayon-lipstick"}', 'https://images.unsplash.com/photo-1586495777744-4413f21062fa?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
    (1068, 'BEAUTY-PLUM-MATTEHEAVEN-PINK-45', 'Plum Matte In Heaven Liquid Lipstick - Pink Power', 'Plum', 'Lipsticks', '100% vegan, smudge-proof, transfer-resistant liquid lipstick enriched with Vitamin E and Sweet Almond Oil for zero-crack comfortable all-day wear.', '{"Product Type": "Clean Liquid Lipstick", "Net Quantity": "4.5 ml", "Key Ingredients": "Sweet Almond Oil, Vitamin E, Kaolin Clay", "Skin Type": "All Skin Tones", "Skin Concerns": "Clean Vegan Color, Non-Drying Matte", "Routine": "AM & PM", "Brand Tier": "Affordable", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://plumgoodness.com/products/matte-in-heaven-liquid-lipstick"}', 'https://images.unsplash.com/photo-1586495777744-4413f21062fa?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
    (1069, 'BEAUTY-COLORBAR-VELVETMATTE-BARE-42', 'Colorbar Velvet Matte Lipstick - Bare', 'Colorbar', 'Lipsticks', 'Timeless creamy velvet matte bullet lipstick that enriches lips with Jojoba and Shea Butter, locking in comfortable peachy-nude hydration for 8 hours.', '{"Product Type": "Creamy Velvet Lipstick", "Net Quantity": "4.2 g", "Key Ingredients": "Jojoba Oil, Shea Butter, Vitamin E", "Skin Type": "Fair to Medium Indian Undertones", "Skin Concerns": "Flaking Lips, Office Nude Color", "Routine": "AM", "Brand Tier": "Affordable", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://www.colorbarcosmetics.com/products/velvet-matte-lipstick"}', 'https://images.unsplash.com/photo-1586495777744-4413f21062fa?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
    (1070, 'BEAUTY-LAKME-FOREVERMATTE-REDCARPET-56', 'Lakme Forever Matte Liquid Lip Colour - Red Carpet', 'Lakme', 'Lipsticks', 'Intense matte liquid lip color with a wand applicator that delivers saturated festive red pigment that stays fresh and smudge-free for 16 hours.', '{"Product Type": "Longwear Liquid Color", "Net Quantity": "5.6 ml", "Key Ingredients": "Lightweight Polymers, Intense Colorants, Vitamin E", "Skin Type": "All Skin Tones", "Skin Concerns": "Festive Wedding Longwear, Budget Red", "Routine": "PM", "Brand Tier": "Affordable", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://www.lakmeindia.com/products/lakme-forever-matte-liquid-lip-colour"}', 'https://images.unsplash.com/photo-1586495777744-4413f21062fa?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
    (1071, 'BEAUTY-MAYBELLINE-CREAMYMATTE-SPICE-39', 'Maybelline Color Sensational Creamy Matte Lipstick - Touch of Spice', 'Maybelline', 'Lipsticks', 'Global viral sensation formulated with nourishing Honey Nectar and precious oils to deliver a velvety soft-matte warm mauve that flatters every skin tone.', '{"Product Type": "Creamy Matte Lipstick", "Net Quantity": "3.9 g", "Key Ingredients": "Honey Nectar, Sesame Seed Oil, Vitamin E", "Skin Type": "Universal Flattering Mauve", "Skin Concerns": "Dry Lips, Versatile Everyday Shade", "Routine": "AM & PM", "Brand Tier": "Drugstore", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://www.maybelline.co.in/lip-makeup/lipstick/color-sensational-creamy-matte-lipstick"}', 'https://images.unsplash.com/photo-1586495777744-4413f21062fa?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
    (1072, 'BEAUTY-MAYBELLINE-AGEREWIND-LIGHT-6', 'Maybelline Instant Age Rewind Eraser Multi-Use Concealer - 120 Light', 'Maybelline', 'Concealers', 'Cult-favorite anti-aging concealer formulated with Haloxyl complex and Goji Berry with an iconic micro-sponge applicator that erases dark circles and fine lines.', '{"Product Type": "Eraser Concealer", "Net Quantity": "6 ml", "Key Ingredients": "Haloxyl Complex, Goji Berry Extract, Dimethicone", "Skin Type": "All Skin Types, Mature Under-Eye", "Skin Concerns": "Dark Circles, Fine Under-Eye Lines, Puffiness", "Routine": "AM", "Brand Tier": "Drugstore", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://www.maybelline.co.in/face-makeup/concealer/instant-age-rewind-eraser-dark-circles-treatment-concealer"}', 'https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
    (1073, 'BEAUTY-LOREAL-INFALLIBLE-CONCEALER-10', 'L''Oreal Paris Infallible Full Wear Concealer - 312 Amber', 'L''Oreal Paris', 'Concealers', 'Maximum full-coverage waterproof liquid concealer equipped with an extra-large doe-foot applicator for seamless all-over face and under-eye camouflage.', '{"Product Type": "Full Wear Liquid Concealer", "Net Quantity": "10 ml", "Key Ingredients": "High-Resistance Polymers, Vitamin E, Dimethicone", "Skin Type": "All Skin Types, Oily, Normal", "Skin Concerns": "Severe Blemish Coverage, Tattoos, Dark Spots", "Routine": "AM", "Brand Tier": "Drugstore", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://www.lorealparis.co.in/infallible/full-wear-more-than-concealer"}', 'https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
    (1074, 'BEAUTY-KAYBEAUTY-HD-CONCEALER-5', 'Kay Beauty HD Liquid Concealer - 120Y Light', 'Kay Beauty', 'Concealers', 'Enriched with Marula Oil and Caffeine to de-puff under-eyes, this HD liquid concealer blurs discoloration and imperfections without settling into creases.', '{"Product Type": "HD Liquid Concealer", "Net Quantity": "5 ml", "Key Ingredients": "Marula Oil, Chamomile Extract, Caffeine, Vitamin E", "Skin Type": "Dry, Normal, Sensitive Under-Eye", "Skin Concerns": "Creasing, Puffy Eyes, Dark Circles", "Routine": "AM", "Brand Tier": "Mid-Range", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://www.nykaa.com/kay-beauty-hd-liquid-concealer/p/723456"}', 'https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
    (1075, 'BEAUTY-MAC-STUDIOFIX-CONCEALER-7', 'M.A.C Studio Fix 24-Hour Smooth Wear Concealer - NC25', 'M.A.C', 'Concealers', 'Professional lightweight liquid concealer with a wand applicator that delivers comfortable, medium-to-full buildable coverage with a natural matte 24-hr finish.', '{"Product Type": "24-Hour Smooth Concealer", "Net Quantity": "7 ml", "Key Ingredients": "Dimethicone, Squalane, Vitamin E, Silica", "Skin Type": "All Skin Types, Oily, Normal", "Skin Concerns": "24-Hour Event Wear, High-Definition Camouflage", "Routine": "AM & PM", "Brand Tier": "Luxury", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://www.maccosmetics.in/product/13844/57813/products/makeup/face/concealer/studio-fix-24-hour-smooth-wear-concealer"}', 'https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
    (1076, 'BEAUTY-SWISS-CONCEALER-02-56', 'Swiss Beauty Liquid Concealer - 02 Sand Sable', 'Swiss Beauty', 'Concealers', 'India''s highest volume budget concealer: creamy blendable semi-matte liquid formula that conceals acne spots and dark circles with zero caking.', '{"Product Type": "Creamy Liquid Concealer", "Net Quantity": "5.6 g", "Key Ingredients": "Beeswax, Titanium Dioxide, Vitamin E, Mineral Pigments", "Skin Type": "All Skin Types", "Skin Concerns": "Daily Spot Concealing, Budget Routine", "Routine": "AM", "Brand Tier": "Affordable", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://swissbeauty.in/products/liquid-concealer"}', 'https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
    (1077, 'BEAUTY-SUGAR-MAGICWAND-10-84', 'Sugar Magic Wand Waterproof Concealer - 10 Latte', 'Sugar Cosmetics', 'Concealers', 'High-performance waterproof concealer wand with Anise Fruit extract that delivers satin matte full coverage to blur hyperpigmentation, puffiness, and acne blemishes.', '{"Product Type": "Waterproof Concealer Wand", "Net Quantity": "8.4 ml", "Key Ingredients": "Anise Fruit Extract, Dimethicone, Silica, Vitamin E", "Skin Type": "Combination, Oily, Normal", "Skin Concerns": "Sweat-Proofing, Deep Pigmentation, Spot Covering", "Routine": "AM", "Brand Tier": "Affordable", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://in.sugarcosmetics.com/products/magic-wand-waterproof-concealer"}', 'https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12'),
    (1078, 'BEAUTY-COLORBAR-FLAWLESS-CONCEALER-6', 'Colorbar Flawless Full Cover Liquid Concealer - Medium', 'Colorbar', 'Concealers', 'Infused with Jojoba Seed Oil and Sunflower Seed Wax, this luminous matte liquid concealer brightens tired eyes while protecting against atmospheric pollution.', '{"Product Type": "Luminous Matte Concealer", "Net Quantity": "6 ml", "Key Ingredients": "Jojoba Seed Oil, Sunflower Seed Wax, Vitamin E", "Skin Type": "Dry, Normal, Combination", "Skin Concerns": "Creasing, Anti-Pollution, Under-Eye Radiance", "Routine": "AM", "Brand Tier": "Mid-Range", "Source": "Manufacturer Official Specification / Open Beauty Facts Reference", "Evidence": "Public Cosmetics Label Declaration / INCI Filing", "Data Status": "catalog_verified", "Product URL": "https://www.colorbarcosmetics.com/products/flawless-full-cover-concealer"}', 'https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?auto=format&fit=crop&w=600&q=80', '2026-11-09 16:51:12');
