INSERT INTO user_routine_items (id, routine_id, product_id, step_number, step_name, custom_product_name, usage_instructions, precautions, created_at) VALUES
    (1, 1, NULL, 1, 'Gentle Cleanser', 'Hydrating Gel Cleanser', 'Massage with lukewarm water for 60 seconds; gently pat dry.', 'Avoid stripping foaming cleansers if skin feels tight.', '2026-11-09 07:13:05'),
    (2, 1, NULL, 2, 'Hydrating Prep Essence', 'Hyaluronic Acid / Ceramide Essence', 'Pat 3-4 drops directly into damp skin until fully absorbed.', 'Apply on damp skin to lock in maximum hydration.', '2026-11-09 07:13:05'),
    (3, 1, NULL, 3, 'Antioxidant Brightener', '10% Vitamin C or Niacinamide Serum', 'Dispense 2-3 drops; press into face and neck.', 'Always pair with SPF 50+ when using daytime brightening actives.', '2026-11-09 07:13:05'),
    (4, 1, NULL, 4, 'Barrier Moisturizer', 'Lightweight Ceramide Gel Cream', 'Smooth evenly across face and neck in upward motions.', 'Do not skip moisturizer even if oily; dehydrated skin overproduces sebum.', '2026-11-09 07:13:05'),
    (5, 1, NULL, 5, 'Broad-Spectrum Sunscreen', 'SPF 50+ PA++++ Fluid Sunscreen', 'Apply two full finger lengths 15 minutes before sun exposure.', 'Non-negotiable daytime step. Reapply every 2-3 hours when outdoors.', '2026-11-09 07:13:05'),
    (6, 2, NULL, 1, 'Double Cleanse', 'Cleansing Balm + Gentle Face Wash', 'Melt sunscreen and makeup with balm; rinse with water-based wash.', 'Ensure cleansing balm emulsifies to milky liquid before rinsing.', '2026-11-09 07:13:05'),
    (7, 2, NULL, 2, 'Active Treatment / Retinoid', 'Gentle Retinol or Multi-Peptide Serum', 'Apply pea-sized amount onto completely dry skin 2-3 nights per week.', 'Do not combine with chemical peeling acids (AHA/BHA) in the same session.', '2026-11-09 07:13:05'),
    (8, 2, NULL, 3, 'Overnight Barrier Recovery Cream', 'Rich Ceramide & Squalane Night Cream', 'Press generously into face, neck, and décolletage before bed.', 'Buffer Retinol between moisturizer layers if you experience initial tingling.', '2026-11-09 07:13:05'),
    (11, 4, 1, 1, 'Cleanser', NULL, NULL, NULL, '2026-11-09 07:20:29'),
