    (310, 95, NULL, 5, 'Broad-Spectrum Sunscreen', 'SPF 50+ PA++++ Fluid Sunscreen', 'Apply two full finger lengths 15 minutes before sun exposure.', 'Non-negotiable daytime step. Reapply every 2-3 hours when outdoors.', '2026-11-09 18:49:08'),
    (311, 96, NULL, 1, 'Double Cleanse', 'Cleansing Balm + Gentle Face Wash', 'Melt sunscreen and makeup with balm; rinse with water-based wash.', 'Ensure cleansing balm emulsifies to milky liquid before rinsing.', '2026-11-09 18:49:08'),
    (312, 96, NULL, 2, 'Active Treatment / Retinoid', 'Gentle Retinol or Multi-Peptide Serum', 'Apply pea-sized amount onto completely dry skin 2-3 nights per week.', 'Do not combine with chemical peeling acids (AHA/BHA) in the same session.', '2026-11-09 18:49:08'),
    (313, 96, NULL, 3, 'Overnight Barrier Recovery Cream', 'Rich Ceramide & Squalane Night Cream', 'Press generously into face, neck, and décolletage before bed.', 'Buffer Retinol between moisturizer layers if you experience initial tingling.', '2026-11-09 18:49:08');
